"""Load-time validation of memory declarations for skills.

The runtime rejects writes to memory entries not declared in a ``memory.yml``
(:meth:`~rasa.mantle.memory.manager.MemoryManager.set`). This module surfaces
that as an *authoring* error at model-load time: it checks that every ordered
block's ``collect`` field and every ``set_memory`` key resolves to a declared entry
(the owning skill's schema or the project schema), so a missing declaration
fails loudly at load instead of mid-conversation.

Checks return :class:`~rasa.mantle.validation_finding.ValidationFinding` objects
rather than raising, so :func:`rasa.mantle.validation.validate_project` can
aggregate them with the other project checks and report every problem at once.
"""

from __future__ import annotations

from rasa.mantle.memory.field import MemoryField
from rasa.mantle.memory.schema import ProjectMemorySchema
from rasa.mantle.skills.catalog import (
    ResolvedActivationTarget,
    SkillCatalog,
    blank_winning_collect_step_id,
    collect_step_descriptions,
    iter_resolved_activation_targets,
    nonempty_description,
    resolved_memory_field_description,
)
from rasa.mantle.skills.skill import Skill
from rasa.mantle.skills.steps import CollectStep, SetMemoryStep
from rasa.mantle.validation_finding import ValidationFinding

_UNDECLARED_MEMORY_CODE = "mantle.validation.memory.undeclared_entry"
_DESCRIPTION_NOT_EXPOSED_CODE = "mantle.validation.memory.description_not_exposed"
_DESCRIPTION_REQUIRED_CODE = "mantle.validation.memory.description_required"
_COLLECT_DESCRIPTION_OVERRIDES_CODE = (
    "mantle.validation.memory.collect_description_overrides"
)
_PROJECT_LLM_SETTABLE_CODE = "mantle.validation.memory.project_llm_settable"
_COLLECT_ON_PROJECT_CODE = "mantle.validation.memory.collect_on_project"
_SKILL_SEED_CODE = "mantle.validation.memory.skill_seed"
_DEFAULT_SKILL_COLLECT_INITIAL_VALUE_CODE = (
    "mantle.validation.memory.default_skill_collect_initial_value"
)


def validate_memory_declarations(
    skill_catalog: SkillCatalog,
    project_memory: ProjectMemorySchema,
) -> list[ValidationFinding]:
    """Check every ``collect`` field and ``set_memory`` key is declared.

    Mirrors :meth:`~rasa.mantle.memory.manager.MemoryManager.set` resolution
    (owning skill's fields, then project fields). A name that resolves to
    neither would be rejected at runtime, so it is reported here at load time.

    Args:
        skill_catalog: The loaded skill catalog (project + default skills).
        project_memory: The project-wide memory schema.

    Returns:
        One :class:`~rasa.mantle.validation_finding.ValidationFinding` per
        ``collect`` field or ``set_memory`` key declared in neither the owning
        skill's nor the project's ``memory.yml``. Empty when all resolve.
    """
    project_fields = set(project_memory.fields)
    findings: list[ValidationFinding] = []
    for skill in skill_catalog.skills.values():
        declared = set(skill.memory.definition.all_fields()) | project_fields
        for target in iter_resolved_activation_targets(skill):
            for step in target.steps:
                if isinstance(step, CollectStep):
                    names = [step.collect]
                elif isinstance(step, SetMemoryStep):
                    names = list(step.set_memory)
                else:
                    continue
                findings.extend(
                    _undeclared_finding(skill.id, target, step.id, name)
                    for name in names
                    if name not in declared
                )
    return findings


def validate_project_memory_not_llm_writable(
    skill_catalog: SkillCatalog,
    project_memory: ProjectMemorySchema,
) -> list[ValidationFinding]:
    """Reject ``llm_settable`` and ``collect`` on project fields.

    Project fields are write-once after the first tool, hook, or seed write.
    The LLM must not set them via ``set_fields`` or ``collect``.
    """
    findings: list[ValidationFinding] = []
    for name, field in project_memory.fields.items():
        if field.llm_settable:
            findings.append(
                ValidationFinding(
                    code=_PROJECT_LLM_SETTABLE_CODE,
                    message=(
                        f"Project memory field {name!r} declares llm_settable: true. "
                        "Project fields cannot be written by the LLM."
                    ),
                )
            )

    project_fields = set(project_memory.fields)
    for skill in skill_catalog.skills.values():
        skill_fields = set(skill.memory.definition.all_fields())
        for target in iter_resolved_activation_targets(skill):
            for step in target.steps:
                if not isinstance(step, CollectStep):
                    continue
                name = step.collect
                if name not in project_fields or name in skill_fields:
                    continue
                location = target.file_path or f"skill {skill.id!r}"
                findings.append(
                    ValidationFinding(
                        code=_COLLECT_ON_PROJECT_CODE,
                        message=(
                            f"Collect step {step.id!r} ({location}) targets "
                            f"project field {name!r}. Project fields cannot be "
                            "collected."
                        ),
                    )
                )
    return findings


def validate_skill_memory_not_seedable(
    skill_catalog: SkillCatalog,
) -> list[ValidationFinding]:
    """Reject ``seed: true`` on skill public and private memory fields.

    Session-start metadata seeding only applies to project fields. A skill
    field with ``seed: true`` would be ignored at runtime.

    Args:
        skill_catalog: The loaded skill catalog (project skills).

    Returns:
        One :class:`~rasa.mantle.validation_finding.ValidationFinding` per
        skill field that declares ``seed: true``. Empty when none do.
    """
    findings: list[ValidationFinding] = []
    for skill in skill_catalog.skills.values():
        schema = skill.memory.definition
        for section, fields in (
            ("public", schema.public),
            ("private", schema.private),
        ):
            for name, field in fields.items():
                if not field.seed:
                    continue
                findings.append(
                    ValidationFinding(
                        code=_SKILL_SEED_CODE,
                        message=(
                            f"Skill {skill.id!r} {section} memory field {name!r} "
                            "declares seed: true. Session-start metadata seeding "
                            "is project-only; remove seed, or declare the field "
                            "on project memory."
                        ),
                    )
                )
    return findings


def validate_default_skill_collect_initial_values(
    skill_catalog: SkillCatalog,
) -> list[ValidationFinding]:
    """Warn when a default skill collect field resets to a non-null initial value.

    Default skills clear declared memory on activation. A non-null
    ``initial_value`` becomes the post-reset slot value, and collect steps
    without ``ask_before_filling`` treat that as already filled and skip the
    ask.
    """
    findings: list[ValidationFinding] = []
    for skill_id, skill in skill_catalog.skills.items():
        if not skill.is_default:
            continue
        for field_name in _collect_fields_skipped_after_reset(skill):
            field = skill.memory.definition.all_fields().get(field_name)
            if field is None or field.initial_value is None:
                continue
            target = _resolved_target_for_collect_field(skill, field_name)
            findings.append(
                _default_skill_collect_initial_value_finding(
                    skill_id,
                    field_name,
                    field,
                    target,
                )
            )
    return findings


def _collect_fields_skipped_after_reset(skill: Skill) -> frozenset[str]:
    """Return collect fields that skip the ask when already at ``initial_value``."""
    skipped: set[str] = set()
    for target in iter_resolved_activation_targets(skill):
        for step in target.steps:
            if isinstance(step, CollectStep) and not step.ask_before_filling:
                skipped.add(step.collect)
    return frozenset(skipped)


def _resolved_target_for_collect_field(
    skill: Skill,
    field_name: str,
) -> ResolvedActivationTarget | None:
    """Return the first resolved target that collects *field_name*, if any."""
    for target in iter_resolved_activation_targets(skill):
        for step in target.steps:
            if isinstance(step, CollectStep) and step.collect == field_name:
                return target
    return None


def _default_skill_collect_initial_value_finding(
    skill_id: str,
    field_name: str,
    field: MemoryField,
    target: ResolvedActivationTarget | None,
) -> ValidationFinding:
    if target is None:
        location = f"skill {skill_id!r}"
    else:
        path = target.file_path or f"skill {skill_id!r}"
        location = f"flow {target.target_id!r}, {path}"
    return ValidationFinding(
        code=_DEFAULT_SKILL_COLLECT_INITIAL_VALUE_CODE,
        severity="warning",
        message=(
            f"Default skill {skill_id!r} collect field {field_name!r} declares "
            f"initial_value {field.initial_value!r} without ask_before_filling. "
            "Activation reset restores that value and the collect step will be "
            "skipped. Leave initial_value unset, or set ask_before_filling: true "
            f"on the collect step ({location})."
        ),
    )


def validate_settable_field_descriptions(
    skill_catalog: SkillCatalog,
    project_memory: ProjectMemorySchema | None = None,
    *,
    require_on: SkillCatalog | None = None,
) -> list[ValidationFinding]:
    """Check descriptions on fields the model can set, and reject the rest.

    A description is allowed only on a skill field the model can set
    (``llm_settable`` or owned by a collect step). A description on any other
    skill field, including bundled default skills, or on a project field is
    rejected. Pass a catalog that includes bundled default skills so those
    fields are checked the same way.

    A field the model can set needs one description the model will see. When
    both a memory description and the winning collect-step description are
    present, the collect-step text wins and training warns. That requirement
    and warning apply to skills in ``require_on`` that are not bundled
    defaults. Bundled defaults, including a project override still marked
    default, are only checked for descriptions the model cannot see.

    Whitespace does not count as a description.

    Args:
        skill_catalog: Skills to check for descriptions the model cannot see.
            Training passes project skills plus bundled default skills.
        project_memory: Project-wide memory schema. Omitted when the project
            has no ``memory.yml``.
        require_on: Skills that must have a description when the model can set
            the field. Defaults to ``skill_catalog``. Training passes the
            project's own skills so bundled defaults are not required to add one.

    Returns:
        Findings for descriptions the model cannot see, missing descriptions
        on fields it can set, and collect-step descriptions that override a
        memory description.
    """
    findings: list[ValidationFinding] = []
    required_ids = frozenset((require_on or skill_catalog).skills)
    for skill_id, skill in skill_catalog.skills.items():
        collect_owned = skill_catalog.collect_owned_entries.get(skill_id, frozenset())
        for name, field in skill.memory.definition.all_fields().items():
            findings.extend(
                _settable_description_findings(
                    skill_id,
                    skill,
                    name,
                    field,
                    collect_owned,
                    require_description=(
                        skill_id in required_ids and not skill.is_default
                    ),
                )
            )
    if project_memory is not None:
        for name, field in project_memory.fields.items():
            if nonempty_description(field.description) is None:
                continue
            findings.append(_project_description_not_exposed_finding(name))
    return findings


def _settable_description_findings(
    skill_id: str,
    skill: Skill,
    name: str,
    field: MemoryField,
    collect_owned: frozenset[str],
    *,
    require_description: bool,
) -> list[ValidationFinding]:
    """Return description findings for one memory field."""
    can_set = field.llm_settable or name in collect_owned
    memory_present = nonempty_description(field.description) is not None
    collect_present = (
        nonempty_description(collect_step_descriptions(skill).get(name)) is not None
    )
    resolved = resolved_memory_field_description(skill, name)
    findings: list[ValidationFinding] = []
    if not can_set and memory_present:
        findings.append(_description_not_exposed_finding(skill_id, name))
    if require_description and can_set and resolved is None:
        findings.append(
            _description_required_finding(
                skill_id,
                name,
                blank_collect_step_id=blank_winning_collect_step_id(skill, name),
            )
        )
    if require_description and can_set and memory_present and collect_present:
        findings.append(_collect_description_overrides_finding(skill_id, name))
    return findings


def _description_not_exposed_finding(skill_id: str, name: str) -> ValidationFinding:
    return ValidationFinding(
        code=_DESCRIPTION_NOT_EXPOSED_CODE,
        message=(
            f"Memory field {name!r} in skill {skill_id!r} declares a "
            "description but is neither llm_settable nor collect-owned. "
            "Descriptions are only surfaced on set_fields for fields the model "
            "can set — remove the description or mark the field settable."
        ),
    )


def _description_required_finding(
    skill_id: str,
    name: str,
    *,
    blank_collect_step_id: str | None = None,
) -> ValidationFinding:
    if blank_collect_step_id is None:
        detail = (
            "Add a description on the memory field, or on the collect step "
            "that fills it."
        )
    else:
        detail = (
            f"Collect step {blank_collect_step_id!r} fills it with a blank "
            "description, which drops an earlier collect-step description. "
            "Add a description on that collect step, or on the memory field."
        )
    return ValidationFinding(
        code=_DESCRIPTION_REQUIRED_CODE,
        message=(
            f"Memory field {name!r} in skill {skill_id!r} can be set by the "
            f"model but has no description. {detail}"
        ),
    )


def _collect_description_overrides_finding(
    skill_id: str, name: str
) -> ValidationFinding:
    return ValidationFinding(
        code=_COLLECT_DESCRIPTION_OVERRIDES_CODE,
        severity="warning",
        message=(
            f"Memory field {name!r} in skill {skill_id!r} declares a "
            "description, but the collect step that fills it also has one. "
            "The collect-step description is the one used wherever the model "
            "sees this field."
        ),
    )


def _project_description_not_exposed_finding(name: str) -> ValidationFinding:
    return ValidationFinding(
        code=_DESCRIPTION_NOT_EXPOSED_CODE,
        message=(
            f"Project memory field {name!r} declares a description. "
            "The model cannot set project fields, so the description is not "
            "shown. Remove the description."
        ),
    )


def _undeclared_finding(
    skill_id: str, target: ResolvedActivationTarget, step_id: str, name: str
) -> ValidationFinding:
    """Build the finding for an undeclared memory entry written by a step."""
    location = target.file_path or f"skill {skill_id!r}"
    return ValidationFinding(
        code=_UNDECLARED_MEMORY_CODE,
        message=(
            f"Memory entry {name!r} is written by step {step_id!r} of flow "
            f"{target.target_id!r} (skill {skill_id!r}, {location}) but is declared "
            "in no memory.yml. Declare it under the owning skill's schema "
            "(public/private) or the project memory.yml."
        ),
    )
